#include <W1jet.hpp>
#include <cmath>
#include <complex>
#include <mxpart_mod.hpp>
#include <sprods_com_mod.hpp>

using namespace mxpart_mod;
using namespace sprods_com_mod;

//     Z. Bern, L. Dixon, D.A. Kosower, e-Print:hep-ph/9708239
//     Eq.10.17
std::complex<double> FFPMccT(int j1, int j2, int j3, int j4, int j5, int j6,
                             FArray2D<std::complex<double>>& za,
                             FArray2D<std::complex<double>>& zb) {

  double delta12, delta34;

  //     Statement functions
  auto zab2 = [&za, &zb](int i1, int i2, int i3, int i4) {
    return za(i1, i2) * zb(i2, i4) + za(i1, i3) * zb(i3, i4);
  };
  auto zab = [&za, &zb](int i1, int i2, int i3) {
    return za(i1, i2) * zb(i2, i3);
  };
  auto zba = [&za, &zb](int i1, int i2, int i3) {
    return zb(i1, i2) * za(i2, i3);
  };
  //     End statement functions

  delta12 = s(j1, j2) - s(j3, j4) - s(j5, j6);
  delta34 = s(j3, j4) - s(j5, j6) - s(j1, j2);

  std::complex<double> FFPMccT_value =
      -std::pow(za(j2, j4), 2) * zb(j1, j6) * zab2(j5, j2, j4, j3)
        / (za(j2, j3) * std::pow(t(j2, j3, j4), 2))
      + 0.5 * zb(j1, j3) * za(j2, j4) * za(j2, j5) * zab2(j5, j2, j4, j3)
        / (za(j2, j3) * zb(j3, j4) * za(j5, j6) * t(j2, j3, j4))
      + 0.5 * std::pow(za(j2, j4), 2) * zb(j1, j6) * zab2(j4, j1, j3, j6)
        / (za(j2, j3) * za(j3, j4) * zb(j5, j6) * t(j2, j3, j4))

      - za(j4, j5) * zab(j2, j1, j3) * zab2(j2, j1, j3, j6)
        / (za(j2, j3) * t(j1, j2, j3) * zab2(j1, j2, j3, j4))

      + 0.5 / (zab2(j1, j2, j3, j4) * zab2(j1, j3, j4, j2))
        * (4.0 * zab(j5, j1, j6) * zab(j4, j2, j3) * zab2(j1, j2, j4, j3) / t(j2, j3, j4)

           + zab2(j1, j2, j4, j3) * std::pow(zab2(j5, j2, j4, j3), 2)
             * (2.0 * s(j3, j4) * s(j5, j6) + delta12 * t(j2, j3, j4))
             / (zb(j3, j4) * za(j5, j6) * std::pow(t(j2, j3, j4), 2))
           + std::pow(zab(j5, j1, j3), 2)
             * (za(j1, j2) * delta12 + zab2(j1, j2, j3, j4) * za(j4, j2))
             / (za(j2, j3) * zb(j3, j4) * za(j5, j6))

           + std::pow(za(j2, j4), 3) * std::pow(zb(j2, j6), 2) * zab2(j1, j2, j3, j4)
             / (za(j2, j3) * za(j3, j4) * zb(j5, j6))
           - za(j2, j4) * za(j4, j5)
             * zab2(j1, j2, j3, j4) * (zab(j4, j1, j6) - zab(j4, j2, j6))
             / (za(j2, j3) * za(j3, j4))
           + za(j1, j2) * zb(j3, j6) * (zab(j5, j1, j3) - zab(j5, j2, j3))
             * (s(j2, j3) + t(j1, j3, j4)) / (za(j2, j3) * zb(j3, j4))

           - za(j1, j2) * za(j4, j5) / za(j2, j3)
             * (zb(j3, j6) * (2.0 * s(j2, j4) + delta34) - 2.0 * zba(j3, j1, j5) * zb(j5, j6)))

      + 0.5 / (zab2(j1, j2, j3, j4) * zab2(j1, j3, j4, j2) * zab2(j3, j1, j2, j4))
        * (zab(j1, j4, j6)
             * (zab(j5, j1, j3) * s(j1, j3) - zab(j5, j2, j3) * s(j2, j3))
           + 5.0 * zab(j1, j2, j4) * zab(j4, j1, j3) * zab(j5, j4, j6)

           + zab(j5, j4, j3) * zab2(j1, j2, j3, j6) * (s(j1, j3) - s(j2, j4))
           + zab(j1, j2, j3)
             * (zab(j5, j2, j6) * s(j3, j4)
                + zab(j5, j4, j6) * s(j1, j3)
                + 2.0 * zab(j2, j1, j4) * za(j4, j3) * zab2(j5, j1, j3, j6) / za(j2, j3)

                + 3.0 * (za(j5, j4) * zb(j4, j3) * za(j3, j1) * zb(j1, j6)
                         - zab(j5, j3, j6) * s(j2, j4))
                - 2.0 * (zab(j5, j1, j6) * (s(j1, j4) + s(j2, j4))
                         + za(j5, j1) * zb(j1, j4) * za(j4, j3) * zb(j3, j6))));

  return FFPMccT_value;
}

extern "C" {

  std::complex<double> FFPMccT_wrapper(int j1, int j2, int j3, int j4, int j5, int j6,
                                       std::complex<double>* fza,
                                       std::complex<double>* fzb) {

    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);

    std::complex<double> FFPMccT_result = FFPMccT(j1, j2, j3, j4, j5, j6, za, zb);  // @coverage-probe
    return FFPMccT_result;
  }

}
